/**
 * Dummy Weight Scale API Server
 * ------------------------------------------------------------
 * Simulates the local client-side weight machine API.
 * Runs on: http://localhost:8765
 *
 * Usage:
 *   node DummyWeightScaleAPI.js
 *
 * Set WeightScaleIP on your machine record to:
 *   http://localhost:8765/weighscale/getweight
 *
 * Response format matches real device:
 *   { API_STATUS, Weight, CAMMODE, CAMERA:[{CAMERA_TYPE, ANPRNO, IMAGE}] }
 * ------------------------------------------------------------
 */

const http = require('http');

const PORT = 8765;
const PATH = '/weighscale/getweight';

// ---- Tiny 1x1 red pixel JPEG in base64 (used as placeholder image) ----
const DUMMY_IMAGE_BASE64 =
    '';

// ---- Sample response data ----
const weightResponse = {
    API_STATUS: "Ok",
    Weight: "34770",
    CAMMODE: 3,
    CAMERA: [
        {
            CAMERA_TYPE: "FRONT",
            ANPRNO: "RJ29GB4472",
            IMAGE: DUMMY_IMAGE_BASE64
        },
        {
            CAMERA_TYPE: "BACK",
            ANPRNO: "unknown",
            IMAGE: DUMMY_IMAGE_BASE64
        }
    ]
};

const server = http.createServer(function (req, res) {
    // ---- CORS headers so browser fetch() from localhost ERP app works ----
    res.setHeader('Access-Control-Allow-Origin', '*');
    res.setHeader('Access-Control-Allow-Methods', 'GET, OPTIONS');
    res.setHeader('Access-Control-Allow-Headers', 'Content-Type');

    if (req.method === 'OPTIONS') {
        res.writeHead(204);
        res.end();
        return;
    }

    const url = req.url.split('?')[0].toLowerCase();

    if (req.method === 'GET' && url === PATH.toLowerCase()) {
        const body = JSON.stringify(weightResponse, null, 2);
        res.writeHead(200, {
            'Content-Type': 'application/json',
            'Content-Length': Buffer.byteLength(body)
        });
        res.end(body);
        console.log('[' + new Date().toLocaleTimeString() + '] GET ' + req.url + ' -> 200 OK  Weight=' + weightResponse.Weight + '  VehicleNo=' + weightResponse.CAMERA[0].ANPRNO);
    } else {
        const notFound = JSON.stringify({ error: 'Not Found', path: req.url });
        res.writeHead(404, { 'Content-Type': 'application/json' });
        res.end(notFound);
        console.log('[' + new Date().toLocaleTimeString() + '] ' + req.method + ' ' + req.url + ' -> 404');
    }
});

server.on('error', function (err) {
    if (err.code === 'EADDRINUSE') {
        console.error('');
        console.error('  ✖  Port ' + PORT + ' is already in use!');
        console.error('     Run this to free it:');
        console.error('       Windows : for /f "tokens=5" %a in (\'netstat -ano ^| findstr :' + PORT + '\') do taskkill /PID %a /F');
        console.error('       PowerShell: Stop-Process -Id (Get-NetTCPConnection -LocalPort ' + PORT + ').OwningProcess -Force');
        console.error('');
    } else {
        console.error('Server error:', err);
    }
    process.exit(1);
});

server.listen(PORT, '127.0.0.1', function () {
    console.log('');
    console.log('  ✔  Dummy Weight Scale API running');
    console.log('     URL : http://localhost:' + PORT + PATH);
    console.log('');
    console.log('  Set WeightScaleIP on your machine record to:');
    console.log('     http://localhost:' + PORT + PATH);
    console.log('');
    console.log('  Press Ctrl+C to stop.');
    console.log('');
});
